// Determine sync scope
const input = $input.first().json;

const syncConfig = {
  sources: [
    {
      name: 'github_repos',
      bridge: 'http://localhost:7811',
      endpoint: '/mcp/repos/list',
      params: { per_page: 100 },
      transform: 'repos'
    },
    {
      name: 'github_issues',
      bridge: 'http://localhost:7811',
      endpoint: '/mcp/issues/list',
      params: { state: 'open', per_page: 100 },
      transform: 'issues'
    },
    {
      name: 'notion_databases',
      bridge: 'native', // Use native Notion MCP
      type: 'notion_search',
      query: '',
      filter: { property: 'object', value: 'database' }
    }
  ],
  destination: {
    bridge: 'http://localhost:7812',
    table_prefix: 'sync_'
  },
  options: {
    upsert: true,
    batch_size: 50,
    conflict_key: 'external_id'
  }
};

return [{ json: { config: syncConfig, triggered_at: new Date().toISOString() } }];

// Transform GitHub repos for storage
const response = $input.first().json;
const repos = response.data?.repos || [];

const transformed = repos.map(repo => ({
  external_id: `github_repo_${repo.id}`,
  source: 'github',
  type: 'repository',
  name: repo.name,
  full_name: repo.full_name,
  description: repo.description,
  url: repo.html_url,
  language: repo.language,
  stars: repo.stargazers_count,
  forks: repo.forks_count,
  open_issues: repo.open_issues_count,
  is_private: repo.private,
  created_at: repo.created_at,
  updated_at: repo.updated_at,
  synced_at: new Date().toISOString()
}));

return [{ json: { table: 'sync_repositories', records: transformed, count: transformed.length } }];

// Transform GitHub issues for storage
const response = $input.first().json;
const issues = response.data?.issues || [];

const transformed = issues.map(issue => ({
  external_id: `github_issue_${issue.id}`,
  source: 'github',
  type: 'issue',
  number: issue.number,
  title: issue.title,
  body: issue.body?.substring(0, 5000), // Truncate long bodies
  state: issue.state,
  url: issue.html_url,
  repository: issue.repository_url?.split('/').slice(-1)[0],
  author: issue.user?.login,
  labels: issue.labels?.map(l => l.name).join(','),
  assignees: issue.assignees?.map(a => a.login).join(','),
  comments_count: issue.comments,
  created_at: issue.created_at,
  updated_at: issue.updated_at,
  synced_at: new Date().toISOString()
}));

return [{ json: { table: 'sync_issues', records: transformed, count: transformed.length } }];

// Transform Slack channels for storage
const response = $input.first().json;
const channels = response.data?.channels || [];

const transformed = channels.map(channel => ({
  external_id: `slack_channel_${channel.id}`,
  source: 'slack',
  type: 'channel',
  name: channel.name,
  topic: channel.topic?.value,
  purpose: channel.purpose?.value,
  is_private: channel.is_private,
  is_archived: channel.is_archived,
  member_count: channel.num_members,
  created_at: new Date(channel.created * 1000).toISOString(),
  synced_at: new Date().toISOString()
}));

return [{ json: { table: 'sync_channels', records: transformed, count: transformed.length } }];

// Batch records for upsert
const items = $input.all();
const batches = [];
const BATCH_SIZE = 50;

for (const item of items) {
  const { table, records } = item.json;

  if (!records || records.length === 0) continue;

  // Split into batches
  for (let i = 0; i < records.length; i += BATCH_SIZE) {
    batches.push({
      table,
      records: records.slice(i, i + BATCH_SIZE),
      batch_index: Math.floor(i / BATCH_SIZE),
      total_batches: Math.ceil(records.length / BATCH_SIZE)
    });
  }
}

return batches.map(b => ({ json: b }));

// Aggregate sync results
const results = $input.all();

const summary = {
  total_batches: results.length,
  successful: 0,
  failed: 0,
  tables: {},
  errors: []
};

for (const result of results) {
  const data = result.json;

  if (data.success) {
    summary.successful++;
    const table = data.table || 'unknown';
    summary.tables[table] = (summary.tables[table] || 0) + (data.count || 0);
  } else {
    summary.failed++;
    summary.errors.push(data.error || 'Unknown error');
  }
}

summary.completed_at = new Date().toISOString();
summary.status = summary.failed === 0 ? 'success' : summary.successful > 0 ? 'partial' : 'failed';

return [{ json: summary }];

